package dev.trydex.fake

/** Images FakeDex serves: a chart (shared media) and a VM screenshot, made by a script so no encoder is needed on device. */
object FakeAssets {
    const val CHART_PNG = ""

    const val DESKTOP_PNG = ""

    /** A stand-in for the Selkies desktop page: an animated "Ubuntu" desktop drawn on a canvas. */
    fun desktopPage(watch: Boolean) = """<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">
<style>html,body{margin:0;height:100%;background:#202124;overflow:hidden}canvas{width:100%;height:100%;display:block}</style></head>
<body><canvas id="c" width="1280" height="720" data-mode="${if (watch) "watch" else "control"}"></canvas><script>
const c=document.getElementById('c'),x=c.getContext('2d');let t=0;const lines=['$ npm test','> vitest run',' ✓ auth.spec.ts (12)',' ✓ chat.spec.ts (48)',' ✓ vm.spec.ts (31)',' ✗ login.spec.ts › retries a stale session',' Test Files  1 failed | 23 passed','$ git status','On branch fix/flaky-login'];
function draw(){t++;const g=x.createLinearGradient(0,0,1280,720);g.addColorStop(0,'#123c35');g.addColorStop(1,'#2b3a8c');x.fillStyle=g;x.fillRect(0,0,1280,720);
x.fillStyle='#202124';x.fillRect(0,0,1280,36);x.fillStyle='#e8eaed';x.font='18px sans-serif';x.fillText('Activities',16,24);x.fillText(new Date().toLocaleTimeString(),580,24);
x.fillStyle='#16181a';x.fillRect(80,90,640,460);x.fillStyle='#3c4043';x.fillRect(80,90,640,32);x.fillStyle='#e8eaed';x.fillText('Terminal — ~/work/dex',96,112);
x.font='17px monospace';const n=Math.min(lines.length,Math.floor(t/25)%(lines.length+6));for(let i=0;i<n;i++){x.fillStyle=lines[i].includes('✗')?'#f28b82':lines[i].startsWith('$')?'#81c995':'#e8eaed';x.fillText(lines[i],100,152+i*26)}
if(t%40<20){x.fillStyle='#e8eaed';x.fillRect(100,152+n*26-16,10,20)}
x.fillStyle='#fafafa';x.fillRect(660,170,540,420);x.fillStyle='#e6e6e6';x.fillRect(660,170,540,34);x.fillStyle='#10b981';x.fillRect(684,230,492,120);x.fillStyle='#fff';x.font='bold 28px sans-serif';x.fillText('localhost:5173',704,300);
for(let i=0;i<6;i++){x.fillStyle='#d4d4d8';x.fillRect(684,376+i*30,420-((i*53+t)%120),14)}requestAnimationFrame(draw)}draw();
</script></body></html>"""
}
